include!("engine_postgres_verification_unpublished.rs");
include!("engine_postgres_verification_websocket.rs");
// Production ordinary-main probes derive every expectation from retained original SQL/files.
// No caller expectations, target-created sessions or complete record constructor.
struct PgOrdinaryApplicationPlan{canonical:PgCanonicalPagePlan,drafts:PgCanonicalDraftPlan,assets:PgCanonicalAssets,history:PgCanonicalHistoryPlan,audience:PgCanonicalAudiencePlan,metadata_flags:Vec<(bool,bool)>,websocket:PgCanonicalWebSocketPlan,unpublished:PgUnpublishedPlan}
impl PgOrdinaryApplicationPlan{
 async fn capture(original:&mut StoppedPgVerificationSource<'_>,audiences:Vec<PgSuppliedAudience>)->anyhow::Result<Self>{
  let canonical=original.canonical_page_plan().await?;let drafts=original.canonical_draft_plan().await?;let assets=original.canonical_asset_plan(&canonical,&drafts).await?;let history=original.canonical_history_plan(&canonical).await?;let audience=original.canonical_audience_plan(&canonical,&drafts,audiences).await?;
  let auth=crate::auth::middleware::AuthUser{claims:original.admin.claims.clone(),api_key_scopes:None};let mut metadata_flags=Vec::new();
  for page in &canonical.pages{metadata_flags.push((crate::spaces::page_metadata::edit_allowed(original.conn,&auth,&page.space,&page.id).await.map_err(|e|anyhow::anyhow!("Original owner metadata capability unavailable:{e:?}"))?,crate::spaces::maintenance::edit_allowed(original.conn,&auth,&page.space,&page.id).await.map_err(|e|anyhow::anyhow!("Original owner maintenance capability unavailable:{e:?}"))?));}
  let unpublished=PgUnpublishedPlan::capture(original,&canonical,&audience).await?;let websocket=PgCanonicalWebSocketPlan::capture(original,&canonical,&audience).await?;original.fence().await?;Ok(Self{canonical,drafts,assets,history,audience,metadata_flags,websocket,unpublished})
 }
}
async fn pg_ordinary_actual_json(client:&reqwest::Client,address:std::net::SocketAddr,token:Option<&str>,uri:&str)->anyhow::Result<(reqwest::StatusCode,serde_json::Value)>{let mut request=client.get(format!("http://{address}/api/v1{uri}"));if let Some(token)=token{request=request.bearer_auth(token);}let mut response=request.send().await?;let status=response.status();let mut bytes=Vec::new();while let Some(chunk)=response.chunk().await?{ensure!(bytes.len().checked_add(chunk.len()).is_some_and(|n|n<=8*1024*1024),"Original application JSON exceeds8MiB");bytes.extend_from_slice(&chunk);}Ok((status,if bytes.is_empty(){serde_json::Value::Null}else{serde_json::from_slice(&bytes)?}))}
async fn pg_ordinary_application_probes(original:&mut StoppedPgVerificationSource<'_>,serving:&RestoredPgServing,process:&mut std::process::Child,address:std::net::SocketAddr,token:&str,plan:&PgOrdinaryApplicationPlan)->anyhow::Result<()> {
 let PgOrdinaryApplicationPlan{canonical,drafts,assets,history,audience,metadata_flags,websocket,unpublished}=plan;
 original.fence().await?;canonical.fence(original)?;drafts.fence(original)?;assets.fence(original).await?;history.fence(original)?;history.verify_target(serving).await?;audience.fence(original).await?;
 let client=reqwest::Client::builder().timeout(std::time::Duration::from_secs(120)).no_proxy().redirect(reqwest::redirect::Policy::none()).build()?;
 for(index,page)in canonical.pages.iter().enumerate(){let prefix=format!("/spaces/{}/documents/{}",urlencoding::encode(&page.space),urlencoding::encode(&page.id));
  for suffix in ["","/content","/versions","/properties"]{let uri=format!("{prefix}{suffix}");let(status,value)=pg_live_observation(original,process,pg_ordinary_actual_json(&client,address,Some(token),&uri)).await?;ensure!(status==reqwest::StatusCode::OK,"Original owner application route refused");match suffix{""=>pg_verify_audience_metadata(&page.metadata,&canonical.content[index]["published_metadata"],metadata_flags[index],&value)?,"/content"=>canonical.verify_content(index,&value)?,"/versions"=>ensure!(value==serde_json::to_value(&page.history)?,"Original history presentation differs"),"/properties"=>ensure!(value==serde_json::to_value(&page.properties)?,"Original property presentation differs"),_=>unreachable!()};let(status,_)=pg_live_observation(original,process,pg_ordinary_actual_json(&client,address,None,&uri)).await?;ensure!(matches!(status.as_u16(),401|403|404),"Anonymous authenticated page route exposed content");}
 }
 for draft in &drafts.drafts{let(status,value)=pg_live_observation(original,process,pg_ordinary_actual_json(&client,address,Some(token),&draft.uri)).await?;ensure!(status==reqwest::StatusCode::OK,"Original draft route refused");drafts.verify(&draft.uri,&value)?;let(status,_)=pg_live_observation(original,process,pg_ordinary_actual_json(&client,address,None,&draft.uri)).await?;ensure!(matches!(status.as_u16(),401|403|404),"Anonymous draft served");}
   let streaming=reqwest::Client::builder().timeout(std::time::Duration::from_secs(120)).redirect(reqwest::redirect::Policy::none()).no_proxy().build()?;
   for (index,route) in &assets.routes{let asset=&assets.assets[*index];assets.fence(original).await?;let uri=format!("http://{address}{route}");pg_live_observation(original,process,async{let mut response=streaming.get(&uri).bearer_auth(token).send().await?;ensure!(response.status()==reqwest::StatusCode::OK,"Actual ordinaryPG exact version route refused");let mut offset=0u64;let mut hash=sha2::Sha256::new();let mut scratch=[0u8;65536];while let Some(chunk)=response.chunk().await?{ensure!(offset.checked_add(chunk.len()as u64).is_some_and(|n|n<=asset.length),"Actual PG binary exceeds original length");for part in chunk.chunks(scratch.len()){ensure!(physical_stamp(&asset.held)?==asset.stamp,"Original PG byte source changed");asset.binding.fence_files().map_err(|e|anyhow::anyhow!(e))?;asset.held.read_exact_at(&mut scratch[..part.len()],offset)?;ensure!(part==&scratch[..part.len()],"Actual PG binary differs from original held bytes");hash.update(part);offset+=part.len()as u64;}}ensure!(offset==asset.length&&hex::encode(hash.finalize())==asset.sha,"Actual ordinaryPG binary length/SHA differs");Ok(())}).await?;assets.fence(original).await?;let denied=pg_live_observation(original,process,async{Ok(streaming.get(&uri).send().await?)}).await?;ensure!(matches!(denied.status().as_u16(),401|403|404),"Anonymous private PG binary served");original.fence().await?;}
   pg_verify_original_legacy(&mut *original,assets,process,address,&streaming,Some(token)).await?;
   for (index,(asset,version))in assets.assets.iter().zip(&assets.versions).enumerate(){let uri=format!("/spaces/{}/documents/{}/attachment-versions/{}",urlencoding::encode(&asset.space),urlencoding::encode(&asset.page),urlencoding::encode(&asset.id));let(status,metadata)=pg_live_observation(original,process,pg_ordinary_actual_json(&streaming,address,Some(token),&uri)).await?;ensure!(status==reqwest::StatusCode::OK&&metadata["version"]==serde_json::to_value(version)?&&metadata["current_space_id"]==asset.space&&metadata["current_document_id"]==asset.page&&metadata["current_storage_path"]==asset.path&&metadata["retirement"]==assets.retirements[index],"Actual original exact version/raw provenance/current association differs");}
   pg_verify_empty_search(original,canonical,unpublished,audience,process,address,&streaming,token,"before_rebuild").await?;
   pg_verify_preindex_private(original,audience,process,address,&streaming,token,canonical,drafts).await?;
   let mut queries=Vec::new();for page in &canonical.pages{let word=page.body.split(|c:char|!c.is_ascii_alphanumeric()).find(|w|w.len()>=8&&w.len()<=100).context("Original PG meaningful search sample absent")?;let uri=format!("/search?q={}&space_id={}&limit=100",urlencoding::encode(word),urlencoding::encode(&page.space));let(status,found)=pg_live_observation(original,process,pg_ordinary_actual_json(&streaming,address,Some(token),&uri)).await?;ensure!(status==reqwest::StatusCode::OK&&found.as_array().is_some_and(|v|v.is_empty()),"Fresh normalPG derived index must be genuinely empty");queries.push((uri,page.id.clone(),page.space.clone(),word.to_owned()));}
   let rebuilt=pg_live_observation(original,process,async{let mut response=streaming.post(format!("http://{address}/api/v1/admin/search/reindex")).bearer_auth(token).send().await?;ensure!(response.status()==reqwest::StatusCode::OK,"Actual normalPG registered rebuild refused");let mut bytes=Vec::new();while let Some(chunk)=response.chunk().await?{ensure!(bytes.len()+chunk.len()<=65536,"Actual PG rebuild response exceeds64KiB");bytes.extend_from_slice(&chunk);}Ok(serde_json::from_slice::<serde_json::Value>(&bytes)?)}).await?;ensure!(rebuilt["status"]=="reindex_complete"&&rebuilt["documents_indexed"].as_u64()==Some(canonical.pages.len()as u64),"Actual PG rebuilt source coverage differs");
   pg_verify_empty_search(original,canonical,unpublished,audience,process,address,&streaming,token,"after_rebuild").await?;
   for(uri,id,space,word)in queries{let(status,found)=pg_live_observation(original,process,pg_ordinary_actual_json(&streaming,address,Some(token),&uri)).await?;ensure!(status==reqwest::StatusCode::OK&&found.as_array().is_some_and(|v|v.iter().any(|h|h["document_id"]==id&&h["space_id"]==space&&h["excerpt"].as_str().is_some_and(|s|s.contains(&word)))),"Actual rebuiltPG search lost original body/page/space");let(status,_)=pg_live_observation(original,process,pg_ordinary_actual_json(&streaming,address,None,&uri)).await?;ensure!(matches!(status.as_u16(),401|403|404),"Anonymous private PG search served");}

 pg_verify_unpublished(original,unpublished,audience,process,address,&streaming,token).await?;
 pg_verify_audiences(original,audience,process,address,&streaming,canonical,drafts,assets).await?;
 pg_verify_original_websocket(original,websocket,audience,process,address,token).await?;
 let private_terms=pg_verify_owner_private_default_search(original,process,address,&streaming,token,canonical,drafts).await?;
 ensure!(drafts.drafts.is_empty()||private_terms>0,"No distinguishing private draft term can certify default-search isolation");
 history.verify_target(serving).await?;history.fence(original)?;assets.fence(original).await?;audience.fence(original).await?;original.fence().await?;Ok(())
}
#[cfg(test)]mod pg_ordinary_credentials_controls{use super::*;#[test]fn untrusted_packet_never_supplies_expectations_or_unbounded_credentials(){let secret="actual-private-configured-authentication-key";for bytes in [b"{}".to_vec(),b"{\"administrator\":\"forged\",\"audiences\":[],\"complete\":true}".to_vec(),vec![b'x';65537]]{assert!(pg_ordinary_credentials(&bytes,secret).is_err());}}}
